package com.dixitdada.journalApp.service; import com.dixitdada.journalApp.entity.*; import com.dixitdada.journalApp.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*; @Service @RequiredArgsConstructor public class JournalService { private final JournalEntryRepository entries; private final UserRepository users; public List<JournalEntry> list(String u){return entries.findAllByOwnerUsernameOrderByCreatedAtDesc(u);} public JournalEntry create(String u,JournalEntry in){in.setId(null);in.setOwnerUsername(u);JournalEntry s=entries.save(in);User x=users.findByUsername(u).orElseThrow();x.getJournalEntryIds().add(s.getId());users.save(x);return s;} public JournalEntry one(String u,String id){JournalEntry e=entries.findById(id).orElseThrow();if(!u.equals(e.getOwnerUsername()))throw new SecurityException("Not your entry");return e;} public JournalEntry update(String u,String id,JournalEntry in){JournalEntry e=one(u,id);e.setTitle(in.getTitle());e.setContent(in.getContent());return entries.save(e);} public void delete(String u,String id){JournalEntry e=one(u,id);entries.delete(e);users.findByUsername(u).ifPresent(x->{x.getJournalEntryIds().remove(id);users.save(x);});} }